-- Generated by Ryoku Settings (Super + ,). Lives in the user_edits overlay,
-- overwritten on every change, so change it in the GUI, not by hand. Loaded
-- after Ryoku's defaults and before your user.lua, which still wins.

hl.config({
  general = { gaps_in = 9, gaps_out = 9, border_size = 1 },
  input = { kb_layout = "us", kb_variant = "", kb_options = "" },
})

hl.curve("ryokuBloom", { type = "bezier", points = { { 0.25, 0.1 }, { 0.25, 1.0 } } })

hl.env("XCURSOR_THEME", "Bibata-Material-Ryoku")
hl.env("XCURSOR_SIZE", "24")
hl.env("HYPRCURSOR_THEME", "Bibata-Material-Ryoku")
hl.env("HYPRCURSOR_SIZE", "24")

hl.env("BROWSER", "zen-browser")

hl.window_rule({ name = "ryoku-tame-maximize-on-open", match = { class = ".*" }, suppress_event = "maximize" })
local function ryoku_plugin_loaded(name)
  for _, p in ipairs(hl.get_loaded_plugins()) do
    if p.name == name then return true end
  end
  return false
end

pcall(function()
  hl.plugin.load("/usr/lib/hyprland/plugins/hyprglass.so")
  if ryoku_plugin_loaded("hyprglass") then
    hl.config({ plugin = { hyprglass = { enabled = 1, default_preset = "clear", blur_strength = 2.0, glass_opacity = 1.0, tint_color = 0x8899aa22, brightness = 1.0, default_theme = "dark" } } })
  end
end)

pcall(function()
  hl.plugin.load("/usr/lib/hyprland/plugins/hyprfocus.so")
  if ryoku_plugin_loaded("hyprfocus") then
    hl.config({ plugin = { hyprfocus = { enable = true, keyboard_focus_animation = "flash", mouse_focus_animation = "none", fade_opacity = 0.8, shrink_percentage = 0.95, slide_height = 20.0 } } })
  end
end)


hl.on("hyprland.start", function()
  hl.exec_cmd("hyprctl setcursor Bibata-Material-Ryoku 24")
end)
